set-variable.value:
@{
      try
      {
        var request = context.Request.Body.As<JObject>(preserveContent: true);
        var id = request?["id"];
        return id == null ? "null" : id.ToString(Newtonsoft.Json.Formatting.None);
      }
      catch
      {
        return "null";
      }
    }

when.set-body:
@{
          var status = (int)context.Response.StatusCode;
          var code = -32000;
          var message = "The upstream MCP server returned an HTTP error.";
          var category = "upstream";
          var retryable = false;

          if (status == 403)
          {
            code = -32001;
            category = "authorization";
            message = "The upstream MCP server denied access.";

            try
            {
              var upstreamBody = context.Response.Body.As<string>(preserveContent: true);
              if (!string.IsNullOrWhiteSpace(upstreamBody))
              {
                var upstreamMessage = upstreamBody.Trim();

                try
                {
                  var upstreamJson = JObject.Parse(upstreamBody);
                  var candidate = upstreamJson.SelectToken("error.message")
                    ?? upstreamJson["message"]
                    ?? upstreamJson["error_description"]
                    ?? upstreamJson["detail"]
                    ?? upstreamJson["error"];

                  if (candidate != null && candidate.Type != JTokenType.Object && candidate.Type != JTokenType.Array)
                  {
                    upstreamMessage = candidate.ToString();
                  }
                }
                catch
                {
                  // The upstream error can be plain text rather than JSON.
                }

                if (!string.IsNullOrWhiteSpace(upstreamMessage))
                {
                  message = upstreamMessage.Length > 4096
                    ? upstreamMessage.Substring(0, 4096)
                    : upstreamMessage;
                }
              }
            }
            catch
            {
              // Keep the safe fallback when the upstream response has no body.
            }
          }
          else if (status == 429)
          {
            code = -32002;
            message = "The upstream MCP server rate limit was exceeded.";
            category = "rate_limit";
            retryable = true;
          }
          else if (status >= 500)
          {
            code = -32003;
            message = "The upstream MCP server is temporarily unavailable.";
            category = "upstream";
            retryable = true;
          }

          JToken requestId;
          try
          {
            requestId = JToken.Parse((string)context.Variables["mcpRequestId"]);
          }
          catch
          {
            requestId = JValue.CreateNull();
          }

          return new JObject(
            new JProperty("jsonrpc", "2.0"),
            new JProperty("id", requestId),
            new JProperty("error", new JObject(
              new JProperty("code", code),
              new JProperty("message", message),
              new JProperty("data", new JObject(
                new JProperty("category", category),
                new JProperty("httpStatus", status),
                new JProperty("retryable", retryable),
                new JProperty("correlationId", (string)context.Variables["correlationId"])
              ))
            ))
          ).ToString(Newtonsoft.Json.Formatting.None);
        }

on-error.set-body:
@{
      var correlationId = context.Variables.GetValueOrDefault<string>("correlationId", context.RequestId.ToString());
      var serializedRequestId = context.Variables.GetValueOrDefault<string>("mcpRequestId", "null");
      JToken requestId;

      try
      {
        requestId = JToken.Parse(serializedRequestId);
      }
      catch
      {
        requestId = JValue.CreateNull();
      }

      return new JObject(
        new JProperty("jsonrpc", "2.0"),
        new JProperty("id", requestId),
        new JProperty("error", new JObject(
          new JProperty("code", -32603),
          new JProperty("message", "API Management could not process the MCP request."),
          new JProperty("data", new JObject(
            new JProperty("category", "gateway"),
            new JProperty("retryable", false),
            new JProperty("correlationId", correlationId)
          ))
        ))
      ).ToString(Newtonsoft.Json.Formatting.None);
    }
